import Wireplumber from 'gi://AstalWp';
import {createBinding, createComputed} from 'gnim';
import Brightness from '#/lib/services/display/brightness';
import Slider from './slider';
import TouchpadOsd from './touchpad';
import Touchpad from '#/lib/services/input/touchpad';
import GObject from 'gnim/gobject';
import Gtk from 'gi://Gtk?version=4.0';
import Astal from 'gi://Astal?version=4.0';
import PopupWindow from '#/widget/common/PopupWindow';
import WindowManager from '#/lib/services/state/windowManager';
import Popup from './popup';

const MUTED_SPEAKER_ICON = 'audio-volume-muted-symbolic';
const MUTED_MIC_ICON = 'microphone-sensitivity-muted-symbolic';
const OSD_WIDTH = 250;
const OSD_MARGIN = 24;
const OSD_SPACING = 12;

export default () => {
    const brightness = Brightness.get_default();
    const audio = Wireplumber.get_default()!.audio;

    const speakerIcon = createComputed(
        [
            createBinding(audio.defaultSpeaker, 'volume'),
            createBinding(audio.defaultSpeaker, 'mute'),
            createBinding(audio.defaultSpeaker, 'volumeIcon'),
        ],
        (volume, mute, volumeIcon) =>
            mute || volume === 0 ? MUTED_SPEAKER_ICON : volumeIcon
    );

    const micIcon = createComputed(
        [
            createBinding(audio.defaultMicrophone, 'volume'),
            createBinding(audio.defaultMicrophone, 'mute'),
            createBinding(audio.defaultMicrophone, 'volumeIcon'),
        ],
        (volume, mute, volumeIcon) =>
            mute || volume === 0 ? MUTED_MIC_ICON : volumeIcon
    );

    const popupList: Gtk.Revealer[] = [
        <Popup
            connectable={audio.defaultSpeaker}
            signals={['notify::volume', 'notify::mute']}
            widget={Slider({
                iconName: speakerIcon,
                value: createBinding(audio.defaultSpeaker, 'volume'),
            })}
        />,

        <Popup
            connectable={brightness}
            signals={['notify::screen']}
            widget={Slider({
                iconName: 'display-brightness-symbolic',
                value: createBinding(brightness, 'screen'),
            })}
        />,

        <Popup
            connectable={brightness}
            signals={['notify::kbd']}
            widget={Slider({
                iconName: 'keyboard-brightness-symbolic',
                value: createBinding(brightness, 'kbd'),
            })}
        />,

        <Popup
            connectable={audio.defaultMicrophone}
            signals={['notify::volume', 'notify::mute']}
            widget={Slider({
                iconName: micIcon,
                value: createBinding(audio.defaultMicrophone, 'volume'),
            })}
        />,

        <Popup
            connectable={Touchpad.get_default()}
            signals={['toggled']}
            widget={<TouchpadOsd />}
        />,
    ];

    return (
        <PopupWindow
            name="osd"
            widthRequest={OSD_WIDTH}
            margin={OSD_MARGIN}
            anchor={Astal.WindowAnchor.BOTTOM}
            layer={Astal.Layer.OVERLAY}
            visible={createComputed(
                (popupList as Gtk.Revealer[]).map(p =>
                    createBinding(p, 'revealChild')
                ),
                (...r: boolean[]) => r.reduce((a, b) => a || b)
            )}
            $={self => WindowManager.get_default().setOsd(self)}
        >
            <Gtk.Box
                cssClasses={['linked', 'card', 'background']}
                css={'box-shadow: none; padding: 12px;'}
                orientation={Gtk.Orientation.VERTICAL}
                valign={Gtk.Align.END}
                spacing={OSD_SPACING}
            >
                {popupList}
            </Gtk.Box>
        </PopupWindow>
    );
};import GObject from 'gi://GObject?version=2.0';
import Gtk from 'gi://Gtk?version=4.0';
import GLib from 'gi://GLib?version=2.0';
import {connectFor} from '#/lib/core/connectFor';

const TIMEOUT_MS = 2000;

export default ({
    widget,
    connectable,
    signals,
}: {
    widget: GObject.Object;
    connectable: GObject.Object;
    signals: string[];
}) => (
    <Gtk.Revealer
        transitionDuration={200}
        revealChild={false}
        visible={false}
        transitionType={Gtk.RevealerTransitionType.SLIDE_UP}
        $={self => {
            let timeoutId: number | null = null;
            let visibilityTimeoutId: number | null = null;
            const showPopup = () => {
                if (timeoutId) clearTimeout(timeoutId);
                if (visibilityTimeoutId) clearTimeout(visibilityTimeoutId);
                self.visible = true;
                self.revealChild = true;
                timeoutId = setTimeout(() => {
                    self.revealChild = false;
                    // eslint-disable-next-line sonarjs/no-nested-functions
                    visibilityTimeoutId = setTimeout(
                        () => (self.visible = false),
                        200
                    );
                }, TIMEOUT_MS);
            };
            // Defer signal connections so OSD widget creation doesn't block
            // the main thread with Wireplumber/Brightness singleton init.
            GLib.idle_add(GLib.PRIORITY_DEFAULT_IDLE, () => {
                for (const signal of signals) {
                    connectFor(self, connectable, signal, showPopup);
                }
                return GLib.SOURCE_REMOVE;
            });
        }}
    >
        {widget}
    </Gtk.Revealer>
);
import Gtk from 'gi://Gtk?version=4.0';
import {Accessor} from 'gnim';

export default ({
    value,
    iconName,
}: {
    value: Accessor<number>;
    iconName: string | Accessor<string>;
}) => (
    <Gtk.Box cssClasses={['slider']} spacing={8}>
        <Gtk.Image iconName={iconName} pixelSize={20} />
        <Gtk.LevelBar
            hexpand
            value={value.as(v => {
                const n = Number(v);
                return Number.isFinite(n) ? Math.max(0, Math.min(1, n)) : 0;
            })}
        />
        <Gtk.Label
            cssClasses={['heading']}
            label={value.as(v =>
                Math.floor((Number.isFinite(Number(v)) ? Number(v) : 0) * 100)
                    .toString()
                    .concat('%')
            )}
        />
    </Gtk.Box>
);
import Gtk from 'gi://Gtk?version=4.0';
import {createBinding} from 'gnim';
import Touchpad from '#/lib/services/input/touchpad';

export default () => {
    const touchpad = Touchpad.get_default();

    return (
        <Gtk.Box spacing={8}>
            <Gtk.Image
                iconName={createBinding(touchpad, 'enabled').as(enabled =>
                    enabled
                        ? 'input-touchpad-symbolic'
                        : 'touchpad-disabled-symbolic'
                )}
                pixelSize={20}
            />
            <Gtk.Label
                hexpand
                cssClasses={['heading']}
                label={createBinding(touchpad, 'enabled').as(enabled =>
                    enabled ? 'Touchpad On' : 'Touchpad Off'
                )}
            />
        </Gtk.Box>
    );
};

