import Gtk from 'gi://Gtk?version=4.0';
import Wireplumber from 'gi://AstalWp';
import GLib from 'gi://GLib?version=2.0';
import {createBinding, createState, For, onMount, onCleanup} from 'gnim';
import AppMixer from '#/lib/services/audio/mixer';
import {usePopoverCleanup} from '#/widget/common/popoverCleanup';
import {connectFor, cleanupNode} from '#/lib/core/connectFor';

export default () => {
    const mixer = AppMixer.get_default();

    const streams = createBinding(mixer, 'streams');
    const [speakers, setSpeakers] = createState<Wireplumber.Endpoint[]>([]);

    onMount(() => {
        const _hn = {};
        // Defer Wireplumber D-Bus proxy to avoid blocking the main loop
        GLib.idle_add(GLib.PRIORITY_DEFAULT_IDLE, () => {
            const audio = Wireplumber.get_default()!.audio;
            const update = () => setSpeakers([...(audio.speakers ?? [])]);
            update();
            connectFor(_hn, audio, 'notify::speakers', update);
            return GLib.SOURCE_REMOVE;
        });
        onCleanup(() => cleanupNode(_hn));
    });

    return (
        <Gtk.Box spacing={12} orientation={Gtk.Orientation.VERTICAL}>
            <For each={streams}>
                {stream => {
                    const id = stream.id;

                    // eslint-disable-next-line sonarjs/no-nested-functions
                    const OutputSelector = () => {
                        let popoverRef: Gtk.Popover | null = null;

                        const label = streams.as(all => {
                            // eslint-disable-next-line sonarjs/no-nested-functions
                            const s = all.find(s => s.id === id);
                            const targetId = s?.targetNode;
                            if (!targetId) return 'Default';
                            // eslint-disable-next-line sonarjs/no-nested-functions
                            const spk = speakers().find(d => d.id === targetId);
                            return spk?.description ?? 'Default';
                        });

                        return (
                            <Gtk.MenuButton
                                visible={speakers.as(s => s.length > 1)}
                                cssClasses={['flat']}
                                tooltipText="Output device"
                                $={usePopoverCleanup}
                                popover={
                                    (
                                        <Gtk.Popover
                                            $={self => {
                                                popoverRef = self;
                                            }}
                                            cssClasses={[]}
                                        >
                                            <Gtk.Box
                                                spacing={4}
                                                cssClasses={['popover-padded']}
                                                orientation={
                                                    Gtk.Orientation.VERTICAL
                                                }
                                            >
                                                <Gtk.Button
                                                    cssClasses={['flat']}
                                                    halign={Gtk.Align.FILL}
                                                    onClicked={() => {
                                                        mixer.setTargetNode(
                                                            id,
                                                            -1
                                                        );
                                                        popoverRef?.popdown();
                                                    }}
                                                >
                                                    <Gtk.Label
                                                        label="Default"
                                                        maxWidthChars={25}
                                                        ellipsize={3}
                                                        halign={Gtk.Align.START}
                                                        cssClasses={['body']}
                                                    />
                                                </Gtk.Button>
                                                <For each={speakers}>
                                                    {speaker => (
                                                        <Gtk.Button
                                                            cssClasses={[
                                                                'flat',
                                                            ]}
                                                            halign={
                                                                Gtk.Align.FILL
                                                            }
                                                            // eslint-disable-next-line sonarjs/no-nested-functions
                                                    onClicked={() => {
                                                                mixer.setTargetNode(
                                                                    id,
                                                                    speaker.id
                                                                );
                                                                popoverRef?.popdown();
                                                            }}
                                                        >
                                                            <Gtk.Label
                                                                label={
                                                                    speaker.description ??
                                                                    ''
                                                                }
                                                                maxWidthChars={
                                                                    25
                                                                }
                                                                ellipsize={3}
                                                                halign={
                                                                    Gtk.Align
                                                                        .START
                                                                }
                                                                cssClasses={[
                                                                    'body',
                                                                ]}
                                                            />
                                                        </Gtk.Button>
                                                    )}
                                                </For>
                                            </Gtk.Box>
                                        </Gtk.Popover>
                                    ) as Gtk.Popover
                                }
                            >
                                <Gtk.Label
                                    cssClasses={['caption']}
                                    maxWidthChars={14}
                                    ellipsize={3}
                                    label={label}
                                />
                            </Gtk.MenuButton>
                        );
                    };

                    return (
                        <Gtk.Box spacing={8} valign={Gtk.Align.CENTER}>
                            <Gtk.Image
                                iconName={
                                    stream.iconName ||
                                    'audio-x-generic-symbolic'
                                }
                                pixelSize={16}
                            />
                            <Gtk.Label
                                label={stream.appName}
                                maxWidthChars={18}
                                ellipsize={3}
                                hexpand
                                halign={Gtk.Align.START}
                                cssClasses={['body']}
                            />
                            <OutputSelector />
                            <Gtk.Button
                                iconName={streams.as(all => {
                                    const s = all.find(x => x.id === id);
                                    return s?.muted
                                        ? 'audio-volume-muted-symbolic'
                                        : 'audio-volume-high-symbolic';
                                })}
                                cssClasses={['flat', 'circular']}
                                onClicked={() => {
                                    const s = mixer.streams.find(
                                        x => x.id === id
                                    );
                                    mixer.setMute(id, !(s?.muted ?? false));
                                }}
                            />
                            <Gtk.Scale
                                widthRequest={100}
                                adjustment={
                                    (
                                        <Gtk.Adjustment
                                            lower={0}
                                            upper={1}
                                            stepIncrement={0.05}
                                            value={stream.volume}
                                        />
                                    ) as Gtk.Adjustment
                                }
                                onValueChanged={self =>
                                    mixer.setVolume(id, self.get_value())
                                }
                            />
                            <Gtk.Label
                                cssClasses={['caption']}
                                widthRequest={36}
                                label={streams.as(all => {
                                    const s = all.find(x => x.id === id);
                                    return `${Math.round((s?.volume ?? 0) * 100)}%`;
                                })}
                            />
                        </Gtk.Box>
                    );
                }}
            </For>
            <Gtk.Box
                visible={streams.as(s => s.length === 0)}
                halign={Gtk.Align.CENTER}
                marginTop={12}
                marginBottom={12}
            >
                <Gtk.Label
                    cssClasses={['body']}
                    label="No active audio streams"
                />
            </Gtk.Box>
        </Gtk.Box>
    );
};
import Gtk from 'gi://Gtk?version=4.0';
import GLib from 'gi://GLib?version=2.0';
import {useSettings} from '#/lib/settings';

try {
    imports.gi.versions.AstalCava = '0.1';
} catch {
    /* ignore */
}

const AstalCava = (() => {
    try {
        return imports.gi.AstalCava;
    } catch {
        return null;
    }
})();

export default () => {
    const settings = useSettings().general;

    if (!AstalCava) {
        return <Gtk.Box visible={false} />;
    }

    return (
        <Gtk.Box
            visible={settings.cavaEnabled}
            orientation={Gtk.Orientation.HORIZONTAL}
            spacing={2}
            halign={Gtk.Align.CENTER}
            valign={Gtk.Align.END}
            cssClasses={['popover-padded']}
            $={self => {
                if (!settings.cavaEnabled()) return;
                const cava = new AstalCava.Cava();
                cava.bars = settings.cavaBars() || 16;
                cava.framerate = settings.cavaFramerate() || 60;
                cava.active = true;

                const bars: Gtk.LevelBar[] = [];
                const barCount = cava.bars;

                for (let i = 0; i < barCount; i++) {
                    const bar = new Gtk.LevelBar();
                    bar.set_min_value(0);
                    bar.set_max_value(1);
                    bar.set_value(0);
                    bar.set_orientation(Gtk.Orientation.VERTICAL);
                    bar.set_inverted(true);
                    bar.set_size_request(6, 40);
                    bar.add_css_class('osd');
                    self.append(bar);
                    bars.push(bar);
                }

                const timer = GLib.timeout_add(
                    GLib.PRIORITY_DEFAULT,
                    1000 / cava.framerate,
                    () => {
                        if (!self.get_parent()) return GLib.SOURCE_REMOVE;
                        const values = cava.get_values();
                        if (!values || !values.length)
                            return GLib.SOURCE_CONTINUE;
                        for (
                            let i = 0;
                            i < Math.min(bars.length, values.length);
                            i++
                        ) {
                            bars[i].set_value(
                                Math.min(1, Math.max(0, values[i]))
                            );
                        }
                        return GLib.SOURCE_CONTINUE;
                    }
                );

                self.connect('destroy', () => {
                    GLib.source_remove(timer);
                    cava.active = false;
                });
            }}
        />
    );
};

