                            for (const n of notifications) {
                                n.dismiss();
                            }
                            return GLib.SOURCE_REMOVE;
                        });
                    }}
                />
            </Gtk.Box>
        );

        return (
            <Gtk.Box spacing={4} orientation={Gtk.Orientation.VERTICAL}>
