                    <Gtk.Box spacing={4} orientation={Gtk.Orientation.VERTICAL}>
                        {notifications.slice(1).map(notif => (
                            <Notification
                                notification={notif}
                                showProgress={showProgress}
                                closeAction={n => n.dismiss()}
                            />
                        ))}
                    </Gtk.Box>
                </Gtk.Revealer>
            </Gtk.Box>
        );
    };

    const HistoryItem = ({
        entry,
    }: {
        entry: {
            id: number;
            appName: string;
            appIcon: string;
            summary: string;
            body: string;
            time: number;
        };
    }) => (
        <Gtk.Box cssClasses={['card']} spacing={8} marginBottom={4}>
