import Gtk from 'gi://Gtk?version=4.0';
import Powerprofiles from './powerprofiles';
import Conservation from './conservation';

import ColorScheme from './colorScheme';
import Bluetooth from './bluetooth';
import Caffeinated from './caffeinated';
import {QuickTimerButton} from '../timer/QuickTimerButton';
import Network from '#/widget/quicksettings/network';
import Screenshot from './screenshot';
import NightLight from './nightLight';
import NightLightLib from '#/lib/services/display/nightLight';
import Touchpad from './touchpad';
import TouchpadLib from '#/lib/services/input/touchpad';

export const ButtonGrid = ({cols = 2}: {cols?: number}) => {
    const nightLight = NightLightLib.get_default();
    const items = [
        <Powerprofiles />,
        <Conservation />,
        <ColorScheme />,
        <Bluetooth />,
        <Network />,
        <Screenshot />,
        <Caffeinated />,
        <QuickTimerButton />,
        nightLight.available ? <NightLight /> : null,
        TouchpadLib.get_default().available ? <Touchpad /> : null,
    ];

    const visibleItems = items.filter(Boolean);

    return (
        <Gtk.Grid
            rowSpacing={4}
            columnSpacing={4}
            columnHomogeneous
            hexpand
            $={self =>
                visibleItems.forEach((item, index) =>
                    self.attach(
                        item as Gtk.Widget,
                        index % cols,
                        Math.floor(index / cols),
                        1,
                        1
                    )
                )
            }
        ></Gtk.Grid>
    );
};
import AstalBluetooth from 'gi://AstalBluetooth';
import Gtk from 'gi://Gtk?version=4.0';
import {createBinding, createComputed, createState, For} from 'gnim';
import {QuickToggleButton} from '#/widget/common/quickToggleButton';
import logger from '#/lib/core/logger';
import {LinkedBox} from '#/widget/common/linkedBox';
import {toArray} from '#/lib/core/gjsUtils';

export default () => {
    // ButtonGrid items only render when quicksettings opens — D-Bus
    // services are already available by then, so synchronous call is safe.
    const bluetooth = AstalBluetooth.get_default();
    const [connectingAddress, setConnectingAddress] = createState<
        string | null
    >(null);

    const isConnecting = connectingAddress.as(addr => addr !== null);

    const popover = (
        <Gtk.Popover cssClasses={[]}>
            <LinkedBox>
                <For
                    each={createBinding(bluetooth, 'devices').as(d =>
                        toArray<AstalBluetooth.Device>(d)
                    )}
                >
                    {(device: AstalBluetooth.Device) => {
                        const deviceConnecting = connectingAddress.as(
                            addr => addr !== null && addr === device.address
                        );

                        return (
                            <Gtk.Button
                                onClicked={() => {
                                    if (device.connected) {
                                        device.disconnect_device((_, res) => {
                                            try {
                                                device.disconnect_device_finish(
                                                    res
                                                );
                                            } catch (e) {
                                                logger.error(
                                                    'bluetooth',
                                                    'disconnect failed:',
                                                    e
                                                );
                                            }
                                        });
                                    } else {
                                        setConnectingAddress(device.address);
                                        device.connect_device((_, res) => {
                                            setConnectingAddress(null);
                                            try {
                                                device.connect_device_finish(
                                                    res
                                                );
                                            } catch (e) {
                                                logger.error(
                                                    'bluetooth',
                                                    'connect failed:',
                                                    e
                                                );
                                            }
                                        });
                                    }
                                }}
                            >
                                <Gtk.Box spacing={8}>
                                    <Gtk.Image
                                        iconName={
                                            device.icon || 'bluetooth-symbolic'
                                        }
                                        pixelSize={16}
                                    />
                                    <Gtk.Label
                                        hexpand
                                        halign={Gtk.Align.START}
                                        label={device.name}
                                    />
                                    <Gtk.Spinner
                                        visible={deviceConnecting}
                                        spinning
                                        marginEnd={4}
                                    />
                                    <Gtk.Image
                                        visible={createBinding(
                                            device,
                                            'connected'
                                        )}
                                        iconName="selection-mode-symbolic"
                                        pixelSize={16}
                                    />
                                </Gtk.Box>
                            </Gtk.Button>
                        );
                    }}
                </For>
            </LinkedBox>
        </Gtk.Popover>
    ) as Gtk.Popover;

    return (
        <QuickToggleButton
            visible={createBinding(bluetooth, 'adapters').as(a => a.length > 0)}
            icon={createComputed(
                [isConnecting, createBinding(bluetooth, 'isPowered')],
                (connecting, powered) => {
                    if (connecting) return 'content-loading-symbolic';
                    return powered ? 'bluetooth-symbolic' : 'bluetooth-disabled-symbolic';
                }
            )}
            cssClasses={createComputed(
                [
                    createBinding(bluetooth, 'isPowered'),
                    createBinding(bluetooth, 'is-connected'),
                ],
                (powered, connected) =>
                    powered && connected
                        ? ['raised', 'suggested-action']
                        : ['raised']
            )}
            label={createComputed(
                [
                    createBinding(bluetooth, 'isPowered'),
                    createBinding(bluetooth, 'is-connected'),
                    createBinding(bluetooth, 'devices'),
                ],
                (powered, _connected) => {
                    if (!powered) return 'Bluetooth Off';
                    const connectedDevices = toArray<AstalBluetooth.Device>(
                        bluetooth.devices
                    ).filter((d: AstalBluetooth.Device) => d.connected);
                    if (connectedDevices.length === 0) return 'Bluetooth';
                    if (connectedDevices.length === 1)
                        return connectedDevices[0].name;
                    return `${connectedDevices.length} connected`;
                }
            )}
            onClick={() => {
                bluetooth.adapter.powered = !bluetooth.adapter.powered;
            }}
            popover={popover}
        />
    );
};
import Inhibit from '#/lib/services/power/inhibit';
import Adw from 'gi://Adw?version=1';
import Gtk from 'gi://Gtk?version=4.0';
import {createBinding, createComputed} from 'gnim';
import {QuickToggleButton} from '#/widget/common/quickToggleButton';
import {LinkedBox} from '#/widget/common/linkedBox';

export default () => {
    const inhibit = Inhibit.get_default();
    const idle = createBinding(inhibit, 'idle');
    const remaining = createBinding(inhibit, 'remaining');

    const label = createComputed(() => {
        const _idle = idle();
        const rem = remaining();
        if (!_idle) return 'Auto Sleep';
        return rem ? `Keep Awake (${rem})` : 'Keep Awake';
    });

    const icon = createComputed(() =>
        idle() ? 'weather-clear-symbolic' : 'weather-clear-night-symbolic'
    );

    const cssClasses = createComputed(() =>
        idle() ? ['raised', 'suggested-action'] : ['raised']
    );

    const popover = (
        <Gtk.Popover cssClasses={[]}>
            <LinkedBox>
                <Gtk.Button onClicked={() => inhibit.setDuration(0)}>
                    <Adw.ButtonContent
                        iconName="weather-clear-symbolic"
                        label="Indefinitely"
                    />
                </Gtk.Button>
                <Gtk.Button onClicked={() => inhibit.setDuration(5)}>
                    <Adw.ButtonContent
                        iconName="preferences-system-time-symbolic"
                        label="5 minutes"
                    />
                </Gtk.Button>
                <Gtk.Button onClicked={() => inhibit.setDuration(15)}>
                    <Adw.ButtonContent
                        iconName="preferences-system-time-symbolic"
                        label="15 minutes"
                    />
                </Gtk.Button>
                <Gtk.Button onClicked={() => inhibit.setDuration(60)}>
                    <Adw.ButtonContent
                        iconName="preferences-system-time-symbolic"
                        label="1 hour"
                    />
                </Gtk.Button>
                <Gtk.Separator visible={createBinding(inhibit, 'idle')} />
                <Gtk.Button
                    visible={createBinding(inhibit, 'idle')}
                    onClicked={() => (inhibit.idle = false)}
                >
                    <Adw.ButtonContent
                        iconName="window-close-symbolic"
                        label="Turn Off"
                    />
                </Gtk.Button>
            </LinkedBox>
        </Gtk.Popover>
    ) as Gtk.Popover;

    return (
        <QuickToggleButton
            cssClasses={cssClasses}
            icon={icon}
            label={label}
            onClick={() => {
                if (inhibit.idle) inhibit.idle = false;
                else inhibit.setDuration(0);
            }}
            popover={popover}
        />
    );
};
import Adw from 'gi://Adw?version=1';
import Gtk from 'gi://Gtk?version=4.0';
import {createBinding} from 'gnim';
import {QuickToggleButton} from '#/widget/common/quickToggleButton';
import {LinkedBox} from '#/widget/common/linkedBox';
import {ColorScheme, DarkModes} from '#/lib/services/display/colorScheme';

export default () => {
    const colorScheme = ColorScheme.get_default();

    const popover = (
        <Gtk.Popover cssClasses={[]}>
            <LinkedBox>
                <Gtk.Button
                    onClicked={() => (colorScheme.colorScheme = DarkModes.AUTO)}
                >
                    <Adw.ButtonContent
                        iconName="night-light-symbolic"
                        label="Automatic"
                    />
                </Gtk.Button>
                <Gtk.Button
                    onClicked={() =>
                        (colorScheme.colorScheme = DarkModes.LIGHT)
                    }
                >
                    <Adw.ButtonContent
                        iconName="weather-clear-symbolic"
                        label="Light Mode"
                    />
                </Gtk.Button>
                <Gtk.Button
                    onClicked={() => (colorScheme.colorScheme = DarkModes.DARK)}
                >
                    <Adw.ButtonContent
                        iconName="weather-clear-night-symbolic"
                        label="Dark Mode"
                    />
                </Gtk.Button>
            </LinkedBox>
        </Gtk.Popover>
    ) as Gtk.Popover;

    return (
        <QuickToggleButton
            icon={createBinding(colorScheme, 'iconName')}
            label={createBinding(colorScheme, 'colorScheme').as(c => {
                if (c === DarkModes.AUTO) return 'Auto';
                if (c === DarkModes.LIGHT) return 'Light Mode';
                return 'Dark Mode';
            })}
            onClick={() => {
                if (colorScheme.colorScheme === DarkModes.LIGHT) {
                    colorScheme.colorScheme = DarkModes.DARK;
                } else if (colorScheme.colorScheme === DarkModes.DARK) {
                    colorScheme.colorScheme = DarkModes.LIGHT;
                } else if (colorScheme.daytime) {
                    colorScheme.colorScheme = DarkModes.DARK;
                } else {
                    colorScheme.colorScheme = DarkModes.LIGHT;
                }
            }}
            popover={popover}
        />
    );
};

