            <Gtk.ScrolledWindow
                widthRequest={360}
                maxContentHeight={350}
                propagateNaturalHeight={true}
                vscrollbarPolicy={Gtk.PolicyType.AUTOMATIC}
                hscrollbarPolicy={Gtk.PolicyType.NEVER}
            >
                <ApList
                    wifi={wifi}
                    connectingAp={connectingAp}
                    setConnectingAp={setConnectingAp}
                />
            </Gtk.ScrolledWindow>
        </Gtk.Box>
    );
};

